import { utilities as csUtils } from '@cornerstonejs/core';
import { getShapeIndexBounds } from '../../../../utilities/sampleAreaAnnotationVoxels.js';
const { createPolylineShape, getSlabHalfWidth, getVoxelThicknessAlongNormal, iterateVoxelsInShape, } = csUtils.voxelSlab;
export const CONTOUR_FILL_COVERAGE = 'centerInside';
export function* iterateContourFillVoxels({ volume, polyline, viewPlaneNormal, imageData, }) {
    if (!(polyline?.length >= 3)) {
        return;
    }
    const planePoint = polyline[0];
    const voxelThickness = getVoxelThicknessAlongNormal(volume, viewPlaneNormal);
    const shape = createPolylineShape({
        volume,
        planePoint,
        viewPlaneNormal,
        polyline,
    });
    for (const { ijk } of iterateVoxelsInShape({
        volume,
        planePoint,
        viewPlaneNormal,
        depthCoverage: CONTOUR_FILL_COVERAGE,
        bounds: getShapeIndexBounds(polyline, volume, imageData, viewPlaneNormal, getSlabHalfWidth(voxelThickness, voxelThickness, CONTOUR_FILL_COVERAGE)),
        getShapeRuns: shape.getRuns,
    })) {
        yield ijk;
    }
}
